const createMessageHandler = jest.fn(() => jest.fn());

jest.unstable_mockModule('./ws/messageHandler.js', () => ({createMessageHandler}));

const {createServer} = await import('./createServer.js');

describe('createServer session store wiring', () => {
  it('passes the configured session store to the message handler', () => {
    const orchestrator = {} as ChatOrchestrator;
    const sessionStore = {} as SessionStore;
    const hal = createServer({
      app: (() => undefined) as unknown as Express,
      wsAuth: jest.fn() as unknown as WsAuthenticator,
      sessionStore,
      orchestrator,
    });

    hal.wss.emit('close');

    expect(createMessageHandler).toHaveBeenCalledWith(orchestrator, sessionStore);
  });
});
